{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Supervised training separation is weakest in Electronics (mean margin 1.8692; negative wins 18.02% of 3,075 positions) and Industrial_and_Scientific (2.7796; 12.52% of 3,116), versus Movies_and_TV (6.6488; 4.27%) and CDs_and_Vinyl (5.4761; 6.01%). These measure fitted training separation, not held-out accuracy.",
    "Deleting recent events reduces descriptive prefix HR@10 by 0.030/0.075/0.055/0.025 across Movies/Industrial/Electronics/CDs, with 200 users/category and no deletion no-ops. This indicates in-sample history dependence; exploratory bootstrap intervals and potentially fitted prefix events do not establish causal effects or validation usefulness.",
    "Pinned validation diagnostic usefulness and original corruption provenance are unavailable in all four categories. NEEDS_IMPROVEMENT reflects these evidence gaps, not demonstrated model failure or established target leakage."
  ],
  "key_implications": [
    "History content affects fitted predictions, while order-stress HR@10 changes are small (0 to −0.009), with 27–37 no-op draws per 2,000/category; artificial permutations provide limited evidence about useful temporal modeling.",
    "Embedding similarity scores of 0.5091–0.5236 measure angular similarity only and cannot establish recommendation diversity; all audited supervised positions contain MASK, but that alone cannot establish leakage absence.",
    "Selection remains host four-category macro validation HR@10; adaptation to those validation results and the shared 43,200 GPU-second search budget constrain interpretation and experimentation."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": -0.5743,
      "Industrial_and_Scientific:pos_neg_margin_p10": -0.288,
      "Industrial_and_Scientific:delete_recent_hr10_delta": -0.075,
      "Industrial_and_Scientific:delete_recent_exploratory_95pct_interval": [-0.13, -0.02],
      "pinned_validation_diagnostic_available": false
    },
    "brief_metric_read": {
      "margin_p10": "Lower-tail supervised training margins are negative in Electronics and Industrial.",
      "delete_recent_hr10_delta": "Paired descriptive training-prefix effect, not host validation or a causal user counterfactual.",
      "pinned_validation_diagnostic_available": "Held-out usefulness cannot be determined from this diagnostic loader."
    }
  }
}
